data.value:
:root {
	font-family: "Segoe UI";
	font-size: 13px;
	padding: 4px 8px;
	color: @WindowText;
}
.comment {
	padding: 10px 10px;
	background-color: @Window;
	border-radius: 4px;
	border: 1px solid @WindowText/0.15;
	box-shadow: 1px 1px 3px #10000000;
}
.hidden {
	display: none;
}
.autogrow-area {
	flex-grow: 1;
}
#editor {
	width: 100%;
	max-width: 100%;
	background-color: @Window;
	height: 4em;
	font-size: 1em;
}
#editor:focus {

}
.buttons {
	display: flex;
	justify-content: flex-end;
	margin-top:8px;
}
.buttons img {
	width: 16px;
	height: 16px;
	margin-left: 12px;
	opacity: 0.7;
	cursor: pointer;
}
.buttons img:hover {
	opacity: 1;
}
.apply-icon {
	fill: @Green;
}
.cancel-icon {
	fill: @Red;
}

