:root {
	font-family: "Segoe UI";
	font-size: 13px;
	padding: 4px 8px;
	color: @WindowText;
}
.comment {
	background-color: @Window;
	border-radius: 4px;
	border: 1px solid @WindowText/0.15;
	box-shadow: 1px 1px 3px #10000000;
	display: flex;
}
:root:select .comment {
	background-color: @Highlight/0.3;
}
.my-comment {
	border-left-color: @Primary;
}
.my-comment .stripe {
	width: 2px;
	min-width: 2px;
	border-radius: 4px 0 0 4px;
	background-color: @Primary;
}
.comment-main {
	padding: 10px 10px 10px 12px;
}
.my-comment .comment-main {
	padding-left: 10px;
}
.hidden {
	display: none;
}
.bold {
	font-weight: bold;
}
.spacer {
	flex-grow: 1;
}
.header {
	display: flex;
	align-items: center;
}
.avatar {	
	margin-right: 10px;
}
.initials {
	color: @White;
	font-weight: bold;
	background-color: @Primary;
	width: 24px;
	height: 24px;
	border-radius: 24px;
	display: flex;
	align-items: center;
	justify-content: center;
}
.photo {
	width:24px;
	height:24px;
	border-radius:24px;
	object-fit:contain;
	background-color:white;
}
.edit-btn {
	cursor: pointer;
	display: none;
}
.my-comment .edit-btn {
	display: block;
}
.edit-icon {
	width: 16px;
	height: 16px;
	fill: @Primary;
	opacity: 0.7;
}
.edit-icon:hover{
	opacity: 1;
}
.header {
	font-size: 0.85em;
}
.author {
	font-weight: bold;
}
.header-meta {
	color: @DisabledText;
	margin-left: 12px;
}
.content {
	margin:8px 0px;
	user-select: text;
}
.footer {
	display: flex;
	justify-content: space-between;
	font-size: 0.85em;
}
.reply-block {
	display: flex;
}
.expand {
	margin-right: 12px;
	color: @Primary;
	cursor: pointer;
	display: flex;
	align-items: center;
}
.arrow-icon {
	width: 12px;
	height: 12px;
	margin-right: 2px;
	fill: @Primary;
}
.reply {
 	cursor: pointer;
}
.reply-icon {
	width:14px;
	height: 14px;
	fill: @Primary;
}
.reply:hover {
	color: @Primary;
}
.reply:hover .reply-icon {
	fill: @Primary;
}
.likes {
	cursor: pointer;	
}
.no-likes {
	visibility: hidden;	
}
.comment:hover .no-likes {
	visibility: visible;
}
.like-icon {
	width: 16px;
	height: 14px;
	fill: @Red;
	opacity: 0.7;
}
.likes:hover .like-icon {
	opacity: 1;
}

.typingbox {
	background-color: @Window;
	color: @WindowText;
	display: flex;
	flex-direction: row;
	align-items: center;
	justify-content: space-between;
	align-self: center;
	padding: 6px 12px;
	border-top: 1px solid @WindowText/0.2;
}

.message {
	flex-grow: 1;
}

.separator {
	width: 1px;
	height: 30px;
	background-color: @WindowText/0.1;
	margin: 0px 12px;
}

.button {
	width: 23px;
	height: 23px;
	opacity: 0.7;
	cursor: pointer;
}

	.button:hover {
		opacity: 1;		
	}
